// Frametop Spatial Toolbar: independent OpenVR host, first hardware slice.
//
// The original bar's arch/visual geometry is reproduced from legacy
// screens/desktop_toolbar.inc and its module X comes from ft_toolbar.py.
// All overlay keys belong to THIS process, not ft-screens or gamepadui.
// The Displays popup is generated by the salvaged ft-taskbar painter.
// Never include legacy *.inc in Frametop core or this host.
#include <openvr.h>
#include <algorithm>
#include <array>
#include <atomic>
#include <chrono>
#include <cmath>
#include <csignal>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <cstddef>
#include <sys/socket.h>
#include <sys/un.h>
#include <cstdlib>
#include <fstream>
#include <filesystem>
#include <iostream>
#include <sstream>
#include <string>
#include <thread>
#include <vector>
#include <sys/wait.h>
#include <unistd.h>

namespace {
constexpr double PI = 3.14159265358979323846;
constexpr double BAR_H = .090;
constexpr double ARCH_DEG = 15;
constexpr double BTN_DZ = .030;
constexpr double TILT_BACK = 20;
constexpr double BUTTON_WIDTH = BAR_H * 85 / 180;
constexpr int BW = 1000;
constexpr int CW = 96;
volatile std::sig_atomic_t stop = 0;
using Mat = vr::HmdMatrix34_t;

struct Item {
    std::string id;
    int x{}, y{}, w{}, h{};
};
struct Surface {
    vr::VROverlayHandle_t handle = vr::k_ulOverlayHandleInvalid;
    bool visible = false;
};

struct Arch {
    double r = 1, h = BAR_H, theta = ARCH_DEG * PI/180;
    double width = 1, top = 0, bottom = 0;
};
void sig(int) { stop = 1; }
Mat identity() {
    Mat p{};
    for (int i=0;i<3;++i) p.m[i][i] = 1;
    return p;
}
Mat mul(const Mat& a, const Mat& b) {
    Mat p{};
    for(int r=0;r<3;++r) {
        for(int c=0;c<3;++c)
            for(int k=0;k<3;++k) p.m[r][c] += a.m[r][k]*b.m[k][c];
        p.m[r][3] = a.m[r][3];
        for(int k=0;k<3;++k) p.m[r][3] += a.m[r][k]*b.m[k][3];
    }
    return p;
}
Mat translation(double x, double y, double z) {
    Mat m=identity();
    m.m[0][3] = float(x); m.m[1][3] = float(y); m.m[2][3] = float(z);
    return m;
}
// Exact legacy screens/vr.cpp orientation formula.
Mat panel_pose(double x,double y,double z,double yaw,double pitch,double roll) {
    const double yw=yaw*PI/180,pt=pitch*PI/180,rl=roll*PI/180;
    const double fx=-std::sin(yw)*std::cos(pt), fy=std::sin(pt),fz=-std::cos(yw)*std::cos(pt);
    const double Z[3]={-fx,-fy,-fz};
    double X[3]={Z[2],0,-Z[0]};
    const double n=std::hypot(X[0],X[2])+1e-12;
    X[0]/=n;X[2]/=n;
    const double Y[3]={Z[1]*X[2]-Z[2]*X[1],Z[2]*X[0]-Z[0]*X[2],Z[0]*X[1]-Z[1]*X[0]};
    const double c=std::cos(rl),s=std::sin(rl);
    Mat m{};
    for(int i=0;i<3;++i){
        m.m[i][0]=float(X[i]*c+Y[i]*s);
        m.m[i][1]=float(Y[i]*c-X[i]*s);
        m.m[i][2]=float(Z[i]);
    }
    m.m[0][3]=float(x);m.m[1][3]=float(y);m.m[2][3]=float(z);
    return m;
}
Arch arch(double metres) {
    Arch a{};
    a.r = std::max(metres / 2, a.h) / a.theta;
    const double margin = a.h*.04;
    a.width=2*(a.r+a.h/2)*std::sin(a.theta)+2*margin;
    a.top=a.h/2+margin;
    a.bottom=(a.r-a.h/2)*std::cos(a.theta)-a.r-margin;
    return a;
}
// Taken from the legacy ArchTexture silhouette calculation.
std::vector<uint8_t> arch_texture(const Arch& a,int w,int h) {
    std::vector<uint8_t> bytes(size_t(w)*h*4,0);
    const double mpp=a.width/w,rc=a.h*(30.0/180.0);
    for(int py=0;py<h;++py) for(int px=0;px<w;++px){
        const double X=(px+.5)*mpp-a.width/2;
        const double Y=a.top-(py+.5)*(a.top-a.bottom)/h+a.r;
        const double rho=std::hypot(X,Y);
        const double side=a.h/2-std::fabs(rho-a.r);
        const double end=rho*std::sin(a.theta-std::fabs(std::atan2(X,Y)));
        double distance=std::min(side,end);
        if(side<rc && end<rc) distance=rc-std::hypot(rc-side,rc-end);
        const double coverage=std::clamp(distance/mpp+.5,0.,1.);
        if(coverage<=0) continue;
        auto *p=&bytes[(size_t(py)*w+px)*4];
        p[0]=0x0e;p[1]=0x14;p[2]=0x1b;p[3]=uint8_t(coverage*255);
    }
    return bytes;
}
std::vector<uint8_t> monitor_button() {
    // Legacy toolbar_taskbar.inc GlyphMonitor / RoundFilledTexture.
    std::vector<uint8_t> data(size_t(CW)*CW*4,0);
    for(int y=0;y<CW;++y) for(int x=0;x<CW;++x) {
        auto *p=&data[(size_t(y)*CW+x)*4];
        const double u=(x+.5-CW/2.)/(CW/2.),v=(CW/2.-y-.5)/(CW/2.);
        const bool inDisc=std::hypot(u,v)<.95;
        if(!inDisc) continue;
        p[0]=0x0e;p[1]=0x14;p[2]=0x1b;p[3]=255;
        const double au=std::fabs(u);
        const bool frame=au<.50 && v>-.14 && v<.40 &&
                         !(au<.39 && v>-.04 && v<.30);
        const bool stand=au<.06 && v<=-.14 && v>-.30;
        const bool base=au<.24 && v<=-.30 && v>-.39;
        if(frame||stand||base) {p[0]=225;p[1]=231;p[2]=235;}
    }
    return data;
}
Mat on_arch(const Arch& a,double u,double dz,bool roll=true,double curve=.75) {
    const double phi=u/a.r;
    double x=a.r*std::sin(phi),y=a.r*std::cos(phi)-a.r;
    x -= a.h*.08*std::sin(phi);
    y -= a.h*.08*std::cos(phi);
    Mat cyl=identity();
    const double c=std::cos(x/curve), s=std::sin(x/curve);
    cyl.m[0][0]=float(c);cyl.m[0][2]=float(-s);
    cyl.m[2][0]=float(s);cyl.m[2][2]=float(c);
    cyl.m[0][3]=float(curve*s-dz*s);
    cyl.m[2][3]=float(curve-curve*c+dz*c);
    Mat output=mul(cyl, translation(0,y,0));
    if(!roll) return output;
    Mat rz=identity();
    rz.m[0][0]=float(std::cos(phi));rz.m[0][1]=float(std::sin(phi));
    rz.m[1][0]=float(-std::sin(phi));rz.m[1][1]=float(std::cos(phi));
    return mul(output,rz);
}
Mat facing_head(const Mat& at,const Mat& hmd) {
    double z[3]={hmd.m[0][3]-at.m[0][3],hmd.m[1][3]-at.m[1][3],hmd.m[2][3]-at.m[2][3]};
    const double len=std::hypot(std::hypot(z[0],z[1]),z[2])+1e-9;
    for(double &v:z) v/=len;
    double x[3]={z[2],0,-z[0]};
    const double n=std::hypot(x[0],x[2])+1e-9;
    x[0]/=n;x[2]/=n;
    const double y[3]={z[1]*x[2]-z[2]*x[1],z[2]*x[0]-z[0]*x[2],z[0]*x[1]-z[1]*x[0]};
    Mat m{};
    for(int i=0;i<3;++i){
        m.m[i][0]=float(x[i]);m.m[i][1]=float(y[i]);m.m[i][2]=float(z[i]);
    }
    for(int i=0;i<3;++i)m.m[i][3]=at.m[i][3];
    return m;
}
struct HmdDiagnostic {
    bool connected=false;
    bool valid=false;
    vr::ETrackingResult tracking=vr::TrackingResult_Uninitialized;
};
bool hmd_pose(Mat& out, HmdDiagnostic* diagnostic=nullptr) {
    vr::TrackedDevicePose_t poses[vr::k_unMaxTrackedDeviceCount]{};
    vr::VRSystem()->GetDeviceToAbsoluteTrackingPose(
        vr::TrackingUniverseStanding,0,poses,vr::k_unMaxTrackedDeviceCount);
    const auto& hmd=poses[vr::k_unTrackedDeviceIndex_Hmd];
    if(diagnostic) {
        diagnostic->connected=hmd.bDeviceIsConnected;
        diagnostic->valid=hmd.bPoseIsValid;
        diagnostic->tracking=hmd.eTrackingResult;
    }
    if(!hmd.bPoseIsValid) return false;
    out=hmd.mDeviceToAbsoluteTracking;
    return true;
}
const char* tracking_name(vr::ETrackingResult result) {
    switch(result){
        case vr::TrackingResult_Uninitialized: return "Uninitialized";
        case vr::TrackingResult_Calibrating_InProgress: return "Calibrating_InProgress";
        case vr::TrackingResult_Calibrating_OutOfRange: return "Calibrating_OutOfRange";
        case vr::TrackingResult_Running_OK: return "Running_OK";
        case vr::TrackingResult_Running_OutOfRange: return "Running_OutOfRange";
        case vr::TrackingResult_Fallback_RotationOnly: return "Fallback_RotationOnly";
        default: return "Unknown";
    }
}
void show(Surface& s,bool on) {
    if(s.handle==vr::k_ulOverlayHandleInvalid || s.visible==on)return;
    if(on) vr::VROverlay()->ShowOverlay(s.handle);
    else vr::VROverlay()->HideOverlay(s.handle);
    s.visible=on;
}
bool create(Surface& s,const char* key,const char* name,const std::vector<uint8_t>& pixel,
            int w,int h,float metres,bool mouse,uint32_t sort) {
    auto *vrO=vr::VROverlay();
    auto err=vrO->CreateOverlay(key,name,&s.handle);
    if(err!=vr::VROverlayError_None) {
        std::fprintf(stderr,"toolbar: create %s failed: %s (is another copy running?)\n",
                     key,vrO->GetOverlayErrorNameFromEnum(err));
        return false;
    }
    err=vrO->SetOverlayRaw(s.handle,(void*)pixel.data(),uint32_t(w),uint32_t(h),4);
    if(err!=vr::VROverlayError_None){
        std::fprintf(stderr,"toolbar: upload %s failed: %s\n",key,vrO->GetOverlayErrorNameFromEnum(err));
        return false;
    }
    vrO->SetOverlayWidthInMeters(s.handle,metres);
    vrO->SetOverlayInputMethod(s.handle,
                              mouse?vr::VROverlayInputMethod_Mouse:vr::VROverlayInputMethod_None);
    // This flag allows SteamVR laser input even when the SteamVR dashboard is closed.
    if(mouse) vrO->SetOverlayFlag(s.handle,vr::VROverlayFlags_MakeOverlaysInteractiveIfVisible,true);
    // Without this aspect, a 10:1 bar makes a giant invisible laser blocker.
    const vr::HmdVector2_t scale={{float(w),float(h)}};
    vrO->SetOverlayMouseScale(s.handle,&scale);
    vrO->SetOverlaySortOrder(s.handle,sort);
    return true;
}
void destroy(Surface& s) {
    if(s.handle!=vr::k_ulOverlayHandleInvalid)
        vr::VROverlay()->DestroyOverlay(s.handle);
    s.handle=vr::k_ulOverlayHandleInvalid;
}
int child_menu(const std::string& script,const std::string& directory,
               const char* action,const std::string& item="",bool detach=false,
               const char* kind="profiles") {
    (void)script; // Renderer is loaded once in menu_worker.py, not fork/exec'ed.
    // All requests stay in the extension-owned private socket. No shell or
    // process spawning on menu clicks. Async actions (desktop launch/profile
    // switching) enqueue work without freezing controller input.
    if(!action||!kind||item.size()>400 ||
       item.find_first_of("\r\n\t")!=std::string::npos)return -1;
    const std::string payload=std::string(action)+"\t"+kind+"\t"+item+"\n";
    const std::string sockpath=directory+"/menu.sock";
    if(sockpath.size()>=sizeof(sockaddr_un::sun_path))return -1;
    const int fd=socket(AF_UNIX,SOCK_STREAM|SOCK_CLOEXEC,0);
    if(fd<0)return -1;
    timeval timeLimit{};
    timeLimit.tv_sec=3;
    setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&timeLimit,sizeof(timeLimit));
    setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&timeLimit,sizeof(timeLimit));
    sockaddr_un addr{};
    addr.sun_family=AF_UNIX;
    std::memcpy(addr.sun_path,sockpath.c_str(),sockpath.size()+1);
    const auto len=socklen_t(offsetof(sockaddr_un,sun_path)+sockpath.size()+1);
    if(connect(fd,reinterpret_cast<sockaddr*>(&addr),len)!=0){
        std::cerr<<"toolbar: renderer socket unavailable: "<<sockpath<<"\n";
        ::close(fd);return -1;
    }
    const auto sent=send(fd,payload.data(),payload.size(),MSG_NOSIGNAL);
    if(sent!=ssize_t(payload.size())){::close(fd);return -1;}
    if(detach){::close(fd);return 0;}
    char response[384]{};
    const ssize_t got=recv(fd,response,sizeof(response)-1,0);
    ::close(fd);
    if(got>=3 && std::string(response,size_t(got)).rfind("ok\n",0)==0)return 0;
    std::cerr<<"toolbar: renderer request "<<action<<"/"<<kind<<" failed: "
             <<(got>0?response:"timeout/disconnected")<<"\n";
    return -1;
}
bool load_layout(const std::string& directory,double& width,double& displayX,
                 double& startX,int& count) {
    std::ifstream in(directory+"/layout.txt");
    return bool(in>>width>>displayX>>startX>>count) &&
           width>=.90 && width<4. && std::abs(displayX)<width/2 &&
           std::abs(startX)<width/2 && count>=0 && count<=12;
}
bool load_popup(const std::string& directory,const std::string& expected,
                std::vector<uint8_t>& bytes,int& width,int& height,
                double& metres,std::vector<Item>& items){
    std::ifstream f(directory+"/popup.txt");
    std::string tag,kind;
    int serial=0;
    if(!(f>>tag>>kind>>serial>>width>>height>>metres) ||
       tag!="popup" || kind!=expected || width<1 || width>1500 ||
       height<1 || height>2500 || metres<=0 || metres>1.5) return false;
    items.clear();
    std::string line;
    std::getline(f,line);
    while(std::getline(f,line)) {
        std::istringstream row(line);
        Item it;
        if(!(row>>tag>>it.id>>it.x>>it.y>>it.w>>it.h) || tag!="item")return false;
        if(it.x<0||it.y<0||it.w<1||it.h<1 ||
           it.x+it.w>width || it.y+it.h>height || items.size()>256)return false;
        items.push_back(it);
    }
    std::ifstream raw(directory+"/popup.rgba",std::ios::binary|std::ios::ate);
    if(!raw) return false;
    const auto size=raw.tellg();
    const size_t expected_bytes=size_t(width)*height*4;
    if(size!=std::streamoff(expected_bytes)) return false;
    bytes.resize(expected_bytes);
    raw.seekg(0);
    return bool(raw.read((char*)bytes.data(),std::streamsize(expected_bytes)));
}
bool load_pixels(const std::string& path,size_t expected,std::vector<uint8_t>& px){
    std::ifstream file(path,std::ios::binary|std::ios::ate);
    if(!file||file.tellg()!=std::streamoff(expected))return false;
    px.resize(expected);
    file.seekg(0);
    return bool(file.read((char*)px.data(),std::streamsize(expected)));
}
struct TaskButton {
    Surface surface;
    std::string id;
    double x=0;
    std::uint64_t pixelsHash=0;
};
std::uint64_t pixel_hash(const std::vector<uint8_t>& bytes){
    // Update task textures only when content changes (e.g. focus underline).
    // Legacy bug: re-uploading the same texture on every hover/event could
    // exhaust OpenVR's raw-texture staging and leave invisible hot buttons.
    std::uint64_t value=14695981039346656037ULL;
    for(uint8_t b:bytes){
        value^=b;
        value*=1099511628211ULL;
    }
    return value;
}
std::vector<uint8_t> start_button(){
    // The original GlyphStart: four square cutouts around the centre of the tile.
    std::vector<uint8_t> data(size_t(CW)*CW*4,0);
    for(int y=0;y<CW;++y)for(int x=0;x<CW;++x){
        uint8_t* p=&data[(size_t(y)*CW+x)*4];
        const double u=(x+.5-CW/2.)/(CW/2.),v=(CW/2.-y-.5)/(CW/2.);
        if(std::abs(u)>=.94||std::abs(v)>=.94)continue;
        p[0]=0x0e;p[1]=0x14;p[2]=0x1b;p[3]=255;
        const double au=std::fabs(u),av=std::fabs(v);
        if(au>.06&&au<.38&&av>.06&&av<.38){
            p[0]=225;p[1]=231;p[2]=235;
        }
    }
    return data;
}
// Exact Frametop upstream screens/vr.cpp: PillTexture / BarTexture.
// Light translucent grey idle; blue only when hovered or actively grabbed.
// Preserve 256x24 texture and its scaled hitbox to avoid "ghost" input.
// Source: https://github.com/Frametop/frametop/blob/main/screens/vr.cpp
std::vector<uint8_t> pill_texture(int w,int h,uint8_t red,uint8_t green,
                                  uint8_t blue,uint8_t alpha){
    std::vector<uint8_t> px(size_t(w)*h*4,0);
    const double r=h/2.0-1;
    for(int y=0;y<h;++y)for(int x=0;x<w;++x){
        const double cx=std::clamp(double(x),r+1,w-r-1);
        const double cy=h/2.0;
        const double distance=std::hypot(x+.5-cx,y+.5-cy);
        uint8_t *p=&px[(size_t(y)*w+x)*4];
        p[0]=red;p[1]=green;p[2]=blue;
        p[3]=uint8_t(std::clamp(r-distance+.5,0.,1.)*alpha);
    }
    return px;
}
const std::vector<uint8_t>& grab_texture(bool lit){
    static const auto normal=pill_texture(256,24,235,235,235,210);
    static const auto active=pill_texture(256,24,90,170,255,240);
    return lit?active:normal;
}
Mat inverse(const Mat& a) {
    Mat m{};
    for(int i=0;i<3;++i)for(int j=0;j<3;++j)m.m[i][j]=a.m[j][i];
    for(int i=0;i<3;++i)for(int j=0;j<3;++j)m.m[i][3]-=m.m[i][j]*a.m[j][3];
    return m;
}
bool tracked_pose(vr::TrackedDeviceIndex_t index,Mat& out) {
    if(index>=vr::k_unMaxTrackedDeviceCount)return false;
    vr::TrackedDevicePose_t poses[vr::k_unMaxTrackedDeviceCount]{};
    vr::VRSystem()->GetDeviceToAbsoluteTrackingPose(
        vr::TrackingUniverseStanding,0,poses,vr::k_unMaxTrackedDeviceCount);
    if(!poses[index].bPoseIsValid)return false;
    out=poses[index].mDeviceToAbsoluteTracking;
    return true;
}
class Toolbar {
    std::string script,dir,popupKind;
    Surface backdrop,start,display,grab;
    // Two persistent popup overlays: the old texture stays visible behind the
    // freshly uploaded one until SteamVR has had time to present it.
    std::array<Surface,2> popups{};
    int activePopup=-1,retiringPopup=-1;
    std::chrono::steady_clock::time_point retirePopupAfter{};
    std::vector<TaskButton> tasks;
    int activeTasks=0,control=-1,popupW=0,popupH=0;
    std::vector<Item> items;
    Mat base=identity(),head=identity(),dragRel=identity();
    Arch a;
    double width=.90,buttonX=.20,startX=-.38,popupMetres=.49,curve=.75;
    double anchorX=0;
    int backingTextureH=0;
    bool shown=false,hoverStart=false,hoverDisplay=false,hoverGrab=false,dragging=false;
    bool grabLit=false;
    vr::TrackedDeviceIndex_t dragDevice=vr::k_unTrackedDeviceIndexInvalid;
    std::filesystem::file_time_type lastTasksTime{};
    std::chrono::steady_clock::time_point nextTaskPoll{};
public:
    Toolbar(std::string p,std::string d):script(std::move(p)),dir(std::move(d)){}
    ~Toolbar(){
        close();
        for(auto &t:tasks)destroy(t.surface);
        for(auto &p:popups)destroy(p);
        destroy(grab);destroy(start);destroy(display);destroy(backdrop);
        if(control>=0)::close(control);
    }
    void close() {
        shown=false;
        popupKind.clear();
        items.clear();
        for(auto &p:popups)show(p,false);
        activePopup=-1;
        retiringPopup=-1;
    }
    void retire_popup_if_ready(){
        if(retiringPopup<0)return;
        if(std::chrono::steady_clock::now()<retirePopupAfter)return;
        // The previous image gave SteamVR three ~16 ms frames to present the
        // newly uploaded one. It is already non-interactive while retiring.
        show(popups[size_t(retiringPopup)],false);
        retiringPopup=-1;
    }
    Mat visual_pose()const{
        const double pitch=std::clamp(-std::atan2(.40,.75)*180/PI-TILT_BACK,-70.,45.);
        return mul(base,panel_pose(0,0,0,0,pitch,0));
    }
    void place(){
        auto *ov=vr::VROverlay();
        const Mat visual=visual_pose();
        const Mat bp=mul(visual,translation(0,(a.top+a.bottom)/2,0));
        ov->SetOverlayWidthInMeters(backdrop.handle,float(a.width));
        ov->SetOverlayCurvature(backdrop.handle,
            float(std::clamp(width/(2*PI*curve),0.,1.)));
        ov->SetOverlayTransformAbsolute(backdrop.handle,vr::TrackingUniverseStanding,&bp);
        const auto cell=[&](Surface& surface,double x,double size){
            if(surface.handle==vr::k_ulOverlayHandleInvalid)return;
            const Mat p=mul(visual,on_arch(a,x,BTN_DZ,true,curve));
            ov->SetOverlayWidthInMeters(surface.handle,float(size));
            ov->SetOverlayTransformAbsolute(surface.handle,vr::TrackingUniverseStanding,&p);
        };
        cell(start,startX,BAR_H*(150.0/180.0)*.9);
        cell(display,buttonX,BUTTON_WIDTH);
        for(int i=0;i<activeTasks;++i)cell(tasks[size_t(i)].surface,tasks[size_t(i)].x,
                                               BAR_H*(150.0/180.0)*.9);
        const double gripWidth=.30;  // upstream default screen chrome width
        const double gripHeight=gripWidth*(24.0/256.0);
        const double gripY=-(BAR_H/2+.012+gripHeight/2);
        const Mat gp=mul(visual,translation(0,gripY,BTN_DZ));
        ov->SetOverlayWidthInMeters(grab.handle,float(gripWidth));
        ov->SetOverlayTransformAbsolute(grab.handle,vr::TrackingUniverseStanding,&gp);
        if(shown)place_popup();
    }
    void place_popup(){
        Mat eye{};
        if(hmd_pose(eye))head=eye;
        const Mat at=mul(visual_pose(),on_arch(a,anchorX,.030,false,curve));
        const double popupHeight=popupMetres*popupH/std::max(1,popupW);
        const Mat pose=mul(facing_head(at,head),
                            translation(0,BAR_H/2+.018+popupHeight/2,0));
        auto *ov=vr::VROverlay();
        if(activePopup>=0){
            auto &p=popups[size_t(activePopup)];
            ov->SetOverlayWidthInMeters(p.handle,float(popupMetres));
            ov->SetOverlayTransformAbsolute(p.handle,vr::TrackingUniverseStanding,&pose);
        }
        if(retiringPopup>=0){
            // Keep the outgoing image at the same pose while it covers the
            // replacement overlay's upload/presentation latency.
            auto &p=popups[size_t(retiringPopup)];
            ov->SetOverlayWidthInMeters(p.handle,float(popupMetres));
            ov->SetOverlayTransformAbsolute(p.handle,vr::TrackingUniverseStanding,&pose);
        }
    }
    bool update_bar(bool first=false) {
        if(child_menu(script,dir,"render","",false,"toolbar")!=0){
            std::cerr<<"toolbar: Python task/layout renderer failed\n";return false;
        }
        double nextWidth=0,nextDisplay=0,nextStart=0;
        int count=0;
        if(!load_layout(dir,nextWidth,nextDisplay,nextStart,count)){
            std::cerr<<"toolbar: invalid toolbar layout\n";return false;
        }
        std::ifstream list(dir+"/tasks.txt");
        std::vector<std::pair<std::string,double>> wanted;
        for(int i=0;i<count;++i){
            std::string tag,id;double x=0;
            if(!(list>>tag>>id>>x)||tag!="task"||!std::isfinite(x)){
                std::cerr<<"toolbar: invalid task tile layout\n";return false;
            }
            wanted.emplace_back(id,x);
        }
        const Arch nextArch=arch(nextWidth);
        const int bh=std::max(8,int(std::lround(BW*
                                  (nextArch.top-nextArch.bottom)/nextArch.width)));
        if(!first&&(backingTextureH!=bh || std::fabs(nextWidth-width)>.001)){
            const auto image=arch_texture(nextArch,BW,bh);
            auto err=vr::VROverlay()->SetOverlayRaw(backdrop.handle,
                                                     (void*)image.data(),BW,bh,4);
            if(err!=vr::VROverlayError_None){
                std::cerr<<"toolbar: keeping last valid backing texture (upload refused)\n";
                return false;
            }
            const vr::HmdVector2_t ms={{float(BW),float(bh)}};
            vr::VROverlay()->SetOverlayMouseScale(backdrop.handle,&ms);
        }
        for(int i=0;i<count;++i) {
            std::vector<uint8_t> rgba;
            if(!load_pixels(dir+"/task-"+std::to_string(i)+".rgba",
                            size_t(128)*128*4,rgba)) {
                std::cerr<<"toolbar: missing task icon "<<i<<"\n";return false;
            }
            const auto digest=pixel_hash(rgba);
            if(i>=int(tasks.size())){
                tasks.emplace_back();
                auto &t=tasks.back();
                const std::string key="tovakai.spatial-toolbar.task."+std::to_string(i);
                if(!create(t.surface,key.c_str(),"Running application",rgba,128,128,
                           .075f,true,3))return false;
                t.pixelsHash=digest;
            }else{
                // Preserve handles, but update a changed focused state or icon.
                // Zero uploads for an identical image and zero overlay recreation.
                auto &t=tasks[size_t(i)];
                if(t.pixelsHash!=digest || t.id!=wanted[size_t(i)].first) {
                    const auto err=vr::VROverlay()->SetOverlayRaw(t.surface.handle,
                                                     rgba.data(),128,128,4);
                    if(err!=vr::VROverlayError_None){
                        std::cerr<<"toolbar: task texture upload refused; retaining previous\n";
                        continue;
                    }
                    const vr::HmdVector2_t ms={{128.f,128.f}};
                    vr::VROverlay()->SetOverlayMouseScale(t.surface.handle,&ms);
                    t.pixelsHash=digest;
                }
            }
            tasks[size_t(i)].id=wanted[size_t(i)].first;
            tasks[size_t(i)].x=wanted[size_t(i)].second;
        }
        for(size_t i=size_t(count);i<tasks.size();++i)show(tasks[i].surface,false);
        width=nextWidth;buttonX=nextDisplay;startX=nextStart;
        a=nextArch;backingTextureH=bh;activeTasks=count;
        if(!first)place();
        return true;
    }
    bool setup(){
        control=socket(AF_UNIX,SOCK_DGRAM|SOCK_NONBLOCK,0);
        if(control<0){std::perror("toolbar: control socket");return false;}
        sockaddr_un addr{};addr.sun_family=AF_UNIX;
        const char name[]="tovakai_toolbar_control";
        std::memcpy(addr.sun_path+1,name,sizeof(name)-1);
        const auto length=socklen_t(offsetof(sockaddr_un,sun_path)+sizeof(name));
        if(bind(control,reinterpret_cast<sockaddr*>(&addr),length)!=0){
            std::perror("toolbar: control socket already bound");return false;
        }
        const auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(15);
        auto nextReport=std::chrono::steady_clock::now();
        HmdDiagnostic tracking{};bool ready=false;int retries=0;
        while(!stop&&std::chrono::steady_clock::now()<deadline){
            if(hmd_pose(head,&tracking)){ready=true;break;}
            if(std::chrono::steady_clock::now()>=nextReport){
                std::cerr<<"toolbar: waiting for HMD tracking (connected="
                         <<int(tracking.connected)<<", pose_valid="<<int(tracking.valid)
                         <<", tracking="<<tracking_name(tracking.tracking)
                         <<", VRSystem connected="
                         <<int(vr::VRSystem()->IsTrackedDeviceConnected(
                                  vr::k_unTrackedDeviceIndex_Hmd))<<")\n";
                nextReport=std::chrono::steady_clock::now()+std::chrono::seconds(3);
            }
            char message[24]{};
            const ssize_t n=recv(control,message,sizeof(message),0);
            if(n==4&&std::memcmp(message,"stop",4)==0){stop=1;break;}
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
            ++retries;
        }
        if(!ready){
            std::cerr<<"toolbar: no valid HMD pose after "<<retries
                     <<" polls. Wake headset and verify tracking.\n";
            return false;
        }
        std::cerr<<"toolbar: HMD tracking ready after "<<retries<<" retries\n";
        const double heading=std::atan2(head.m[0][2],head.m[2][2])*180/PI;
        base=panel_pose(head.m[0][3]-std::sin(heading*PI/180)*.75,
                        head.m[1][3]-.40,
                        head.m[2][3]-std::cos(heading*PI/180)*.75,
                        heading,0,0);
        // The Python layout is computed first, but NO overlay is created
        // until the complete Start/Tasks/Displays geometry is known.
        if(!update_bar(true))return false;
        const auto image=arch_texture(a,BW,backingTextureH);
        if(!create(backdrop,"tovakai.spatial-toolbar.backing","Frametop Toolbar",
                   image,BW,backingTextureH,float(a.width),false,1))return false;
        if(!create(start,"tovakai.spatial-toolbar.start","Frametop Start",
                   start_button(),CW,CW,.075f,true,3))return false;
        if(!create(display,"tovakai.spatial-toolbar.displays","Frametop Displays",
                   monitor_button(),CW,CW,float(BUTTON_WIDTH),true,3))return false;
        if(!create(grab,"tovakai.spatial-toolbar.grab","Toolbar move handle",
                   grab_texture(false),256,24,.30f,true,3))return false;
        // Upstream allows continuous thumbstick up/down while holding the grab
        // trigger by asking OpenVR for repeated discrete scroll events.
        if(vr::VROverlay()->SetOverlayFlag(
               grab.handle,vr::VROverlayFlags_SendVRDiscreteScrollEvents,true)
           !=vr::VROverlayError_None){
            std::cerr<<"toolbar: failed to enable thumbstick scroll on grab bar\n";
            return false;
        }
        const std::vector<uint8_t> blank(4*4*4,0);
        if(!create(popups[0],"tovakai.spatial-toolbar.popup","Frametop Toolbar Menu A",
                   blank,4,4,.49f,true,4))return false;
        if(!create(popups[1],"tovakai.spatial-toolbar.popup.swap",
                   "Frametop Toolbar Menu B",blank,4,4,.49f,true,4))return false;
        // The old task renderer may have written icons before overlay startup.
        // Request one refresh now that the backing/controls exist.
        if(!update_bar(false))return false;
        place();
        show(backdrop,true);show(start,true);show(display,true);show(grab,true);
        for(int i=0;i<activeTasks;++i)show(tasks[size_t(i)].surface,true);
        nextTaskPoll=std::chrono::steady_clock::now()+std::chrono::seconds(2);
        return true;
    }
    void open(const std::string& kind,double x,bool toggle=true){
        if(toggle&&shown&&popupKind==kind){close();return;}
        if(kind!="start"&&kind!="profiles")return;
        if(child_menu(script,dir,"render","",false,kind.c_str())!=0){
            std::cerr<<"toolbar: "<<kind<<" popup render failed\n";return;
        }
        std::vector<uint8_t> pixels;
        std::vector<Item> boxes;
        int w=0,h=0;double metres=0;
        if(!load_popup(dir,kind,pixels,w,h,metres,boxes)){
            std::cerr<<"toolbar: invalid "<<kind<<" popup buffer\n";return;
        }
        auto *ov=vr::VROverlay();
        // Upload to the HIDDEN, inactive overlay. Updating the currently
        // visible OpenVR raw texture caused a black frame on category changes.
        // Keep both handles pooled; never destroy/recreate on navigation.
        const int stage=(activePopup<0)?0:1-activePopup;
        auto &incoming=popups[size_t(stage)];
        if(retiringPopup==stage){
            // Rapid consecutive category clicks: reclaim the previous page
            // only after making it non-interactive. The current page remains.
            show(incoming,false);
            retiringPopup=-1;
        }
        const auto err=ov->SetOverlayRaw(incoming.handle,pixels.data(),
                                        uint32_t(w),uint32_t(h),4);
        if(err!=vr::VROverlayError_None){
            std::cerr<<"toolbar: popup texture rejected; current menu stays visible: "
                     <<ov->GetOverlayErrorNameFromEnum(err)<<"\n";
            return;
        }
        const vr::HmdVector2_t mouseScale={{float(w),float(h)}};
        ov->SetOverlayMouseScale(incoming.handle,&mouseScale);
        const double popupHeight=metres*h/double(w);
        const Mat at=mul(visual_pose(),on_arch(a,x,.030,false,curve));
        Mat eye{};
        if(hmd_pose(eye))head=eye;
        const Mat pose=mul(facing_head(at,head),
                           translation(0,BAR_H/2+.018+popupHeight/2,0));
        ov->SetOverlayWidthInMeters(incoming.handle,float(metres));
        ov->SetOverlayTransformAbsolute(incoming.handle,vr::TrackingUniverseStanding,&pose);
        ov->SetOverlaySortOrder(incoming.handle,5);
        ov->SetOverlayInputMethod(incoming.handle,vr::VROverlayInputMethod_Mouse);
        // New overlay is presented in front, old one remains behind as a
        // temporary fallback. Only one overlay may receive pointer input.
        const auto showErr=ov->ShowOverlay(incoming.handle);
        if(showErr!=vr::VROverlayError_None){
            std::cerr<<"toolbar: popup presentation failed; retaining current menu: "
                     <<ov->GetOverlayErrorNameFromEnum(showErr)<<"\n";
            return;
        }
        incoming.visible=true;
        const int previous=activePopup;
        if(previous>=0){
            auto &outgoing=popups[size_t(previous)];
            ov->SetOverlaySortOrder(outgoing.handle,4);
            ov->SetOverlayInputMethod(outgoing.handle,vr::VROverlayInputMethod_None);
            retiringPopup=previous;
            retirePopupAfter=std::chrono::steady_clock::now()+
                             std::chrono::milliseconds(55);
        }
        activePopup=stage;
        popupW=w;popupH=h;popupMetres=metres;items=std::move(boxes);
        anchorX=x;popupKind=kind;shown=true;
    }
    void click(int x,int y){
        for(auto it=items.rbegin();it!=items.rend();++it){
            if(x<it->x||x>=it->x+it->w||y<it->y||y>=it->y+it->h)continue;
            const std::string kind=popupKind,item=it->id;
            std::cerr<<"toolbar: "<<kind<<" click "<<item<<"\n";
            // Pagination/category changes refresh the same existing popup.
            const bool refresh=(kind=="start"&&
                (item.rfind("cat:",0)==0||item.rfind("page:",0)==0));
            if(refresh){
                if(child_menu(script,dir,"activate",item,false,kind.c_str())==0)
                    open(kind,anchorX,false);
                return;
            }
            child_menu(script,dir,"activate",item,true,kind.c_str());
            close();
            return;
        }
        close();
    }
    void light_grab(bool lit){
        if(grabLit==lit)return;
        const auto &px=grab_texture(lit);
        const auto err=vr::VROverlay()->SetOverlayRaw(
            grab.handle,const_cast<uint8_t*>(px.data()),256,24,4);
        if(err!=vr::VROverlayError_None){
            std::cerr<<"toolbar: grab highlight upload refused; retaining previous\n";
            return;
        }
        grabLit=lit;
    }
    void push_drag(double notches){
        // Frametop upstream screens/vr.cpp Push(): change the distance from
        // HEAD to held panel, NOT the controller's local Z. Recompute the
        // controller-relative grab offset so subsequent arm motion is seamless.
        if(!dragging||!std::isfinite(notches)||notches==0)return;
        Mat controller{},eye{};
        if(!tracked_pose(dragDevice,controller)||!hmd_pose(eye))return;
        Mat pose=mul(controller,dragRel);
        const double dx=double(pose.m[0][3])-eye.m[0][3];
        const double dy=double(pose.m[1][3])-eye.m[1][3];
        const double dz=double(pose.m[2][3])-eye.m[2][3];
        const double length=std::sqrt(dx*dx+dy*dy+dz*dz);
        if(!(length>1e-6))return;
        const double target=std::clamp(length*(1.+.08*notches),.3,10.);
        pose.m[0][3]=float(eye.m[0][3]+dx/length*target);
        pose.m[1][3]=float(eye.m[1][3]+dy/length*target);
        pose.m[2][3]=float(eye.m[2][3]+dz/length*target);
        dragRel=mul(inverse(controller),pose);
        drag_tick(); // immediately move the entire toolbar as one unit
    }
    void drag_start(vr::TrackedDeviceIndex_t index){
        Mat controller{};
        if(dragging||!tracked_pose(index,controller)){
            std::cerr<<"toolbar: drag ignored (controller pose unavailable)\n";return;
        }
        dragRel=mul(inverse(controller),base);
        dragDevice=index;dragging=true;
        light_grab(true);
        close();std::cerr<<"toolbar: drag started on controller "<<index<<"\n";
    }
    void drag_end(vr::TrackedDeviceIndex_t index){
        if(!dragging||dragDevice!=index)return;
        dragging=false;
        dragDevice=vr::k_unTrackedDeviceIndexInvalid;
        light_grab(hoverGrab);
        Mat h{};
        if(hmd_pose(h))curve=std::clamp(std::hypot(
            double(h.m[0][3]-base.m[0][3]),
            double(h.m[2][3]-base.m[2][3])),.45,4.0);
        place();
        std::cerr<<"toolbar: drag released; position remains world-anchored\n";
    }
    void drag_tick(){
        if(!dragging)return;
        Mat controller{};
        if(!tracked_pose(dragDevice,controller))return;
        const Mat carried=mul(controller,dragRel);
        const double yaw=std::atan2(carried.m[0][2],carried.m[2][2])*180/PI;
        base=panel_pose(carried.m[0][3],carried.m[1][3],carried.m[2][3],yaw,0,0);
        place();
    }
    void set_visible(bool visible){
        if(!visible){
            close();
            dragging=false;
            dragDevice=vr::k_unTrackedDeviceIndexInvalid;
            hoverGrab=false;
            light_grab(false);
        }
        show(backdrop,visible);
        show(start,visible);show(display,visible);show(grab,visible);
        for(int i=0;i<activeTasks;++i)show(tasks[size_t(i)].surface,visible);
    }
    void maybe_refresh_tasks(){
        const auto now=std::chrono::steady_clock::now();
        if(now<nextTaskPoll||dragging)return;
        nextTaskPoll=now+std::chrono::seconds(2);
        std::error_code err;
        const auto time=std::filesystem::last_write_time(dir+"/tasks.json",err);
        if(err||time==lastTasksTime)return;
        if(update_bar(false)){
            lastTasksTime=time;
            for(int i=0;i<activeTasks;++i)show(tasks[size_t(i)].surface,true);
            std::cerr<<"toolbar: task feed now has "<<activeTasks<<" tiles\n";
        }
    }
    void loop(){
        auto *ov=vr::VROverlay();
        bool lastShown=true;
        while(!stop){
            char command[24]{};
            if(recv(control,command,sizeof(command),0)==4 &&
               std::memcmp(command,"stop",4)==0){stop=1;break;}
            const bool dashboard=ov->IsDashboardVisible();
            const char* overrideScene=std::getenv("FT_TOOLBAR_ALLOW_SCENE");
            const bool allowScene=overrideScene&&overrideScene[0]=='1';
            const bool scene=!allowScene&&vr::VRApplications()&&
                vr::VRApplications()->GetCurrentSceneProcessId()!=0;
            const bool visible=!(dashboard||scene);
            if(visible!=lastShown){set_visible(visible);lastShown=visible;}
            if(visible) {
                maybe_refresh_tasks();
                drag_tick();
            }
            vr::VREvent_t ev{};
            while(ov->PollNextOverlayEvent(start.handle,&ev,sizeof(ev))){
                if(!visible)continue;
                if(ev.eventType==vr::VREvent_MouseButtonUp)drag_end(ev.trackedDeviceIndex);
                if(ev.eventType==vr::VREvent_FocusEnter||ev.eventType==vr::VREvent_MouseMove)
                    hoverStart=true;
                if(ev.eventType==vr::VREvent_FocusLeave)hoverStart=false;
                if(ev.eventType==vr::VREvent_MouseButtonDown &&
                   ev.data.mouse.button==vr::VRMouseButton_Left)open("start",startX);
            }
            while(ov->PollNextOverlayEvent(display.handle,&ev,sizeof(ev))){
                if(!visible)continue;
                if(ev.eventType==vr::VREvent_MouseButtonUp)drag_end(ev.trackedDeviceIndex);
                if(ev.eventType==vr::VREvent_FocusEnter||ev.eventType==vr::VREvent_MouseMove)
                    hoverDisplay=true;
                if(ev.eventType==vr::VREvent_FocusLeave)hoverDisplay=false;
                if(ev.eventType==vr::VREvent_MouseButtonDown &&
                   ev.data.mouse.button==vr::VRMouseButton_Left)open("profiles",buttonX);
            }
            for(int i=0;i<activeTasks;++i){
                auto &task=tasks[size_t(i)];
                while(ov->PollNextOverlayEvent(task.surface.handle,&ev,sizeof(ev))){
                    if(!visible)continue;
                    if(ev.eventType==vr::VREvent_MouseButtonUp)drag_end(ev.trackedDeviceIndex);
                    if(ev.eventType==vr::VREvent_MouseButtonDown &&
                       ev.data.mouse.button==vr::VRMouseButton_Left){
                        child_menu(script,dir,"activate",task.id,true,"task");
                        close();
                    }
                }
            }
            while(ov->PollNextOverlayEvent(grab.handle,&ev,sizeof(ev))){
                if(!visible)continue;
                if(ev.eventType==vr::VREvent_MouseButtonUp)drag_end(ev.trackedDeviceIndex);
                if(ev.eventType==vr::VREvent_FocusEnter||ev.eventType==vr::VREvent_MouseMove)
                    hoverGrab=true;
                if(ev.eventType==vr::VREvent_FocusLeave)hoverGrab=false;
                if(ev.eventType==vr::VREvent_MouseButtonDown &&
                   ev.data.mouse.button==vr::VRMouseButton_Left)
                    drag_start(ev.trackedDeviceIndex);
                if(ev.eventType==vr::VREvent_MouseButtonUp)
                    drag_end(ev.trackedDeviceIndex);
                if(ev.eventType==vr::VREvent_ScrollDiscrete&&dragging &&
                   ev.trackedDeviceIndex==dragDevice)
                    push_drag(ev.data.scroll.ydelta);
                light_grab(hoverGrab||dragging);
            }
            // Poll both handles so stale events cannot accumulate when a
            // formerly interactive page retires. Only the active menu clicks.
            for(int index=0;index<2;++index){
                while(ov->PollNextOverlayEvent(popups[size_t(index)].handle,&ev,sizeof(ev))){
                    if(!visible||!shown||index!=activePopup)continue;
                    if(ev.eventType==vr::VREvent_MouseButtonUp)drag_end(ev.trackedDeviceIndex);
                    if(ev.eventType==vr::VREvent_MouseButtonDown &&
                       ev.data.mouse.button==vr::VRMouseButton_Left)
                        click(int(ev.data.mouse.x),popupH-int(ev.data.mouse.y));
                }
            }
            retire_popup_if_ready();
            ov->SetOverlayAlpha(start.handle,hoverStart||popupKind=="start"?1.f:.88f);
            ov->SetOverlayAlpha(display.handle,hoverDisplay||popupKind=="profiles"?1.f:.88f);
            // Match upstream's idle opacity; active highlight uses blue RGBA.
            ov->SetOverlayAlpha(grab.handle,hoverGrab||dragging?1.f:.55f);
            while(waitpid(-1,nullptr,WNOHANG)>0){}
            std::this_thread::sleep_for(std::chrono::milliseconds(16));
        }
    }
};
} // namespace

int main(int argc,char**argv){
    if(argc!=3){
        std::cerr<<"usage: ft-toolbar <absolute-menu.py> <private-runtime-dir>\n";
        return 2;
    }
    std::signal(SIGINT,sig);
    std::signal(SIGTERM,sig);
    vr::EVRInitError err=vr::VRInitError_None;
    vr::VR_Init(&err,vr::VRApplication_Overlay);
    if(err!=vr::VRInitError_None) {
        std::cerr<<"toolbar: OpenVR init failed: "<<vr::VR_GetVRInitErrorAsEnglishDescription(err)<<"\n";
        return 1;
    }
    int rc=0;
    {
        Toolbar host(argv[1],argv[2]);
        if(host.setup()){
            std::cerr<<"toolbar: independent Displays overlay running (Ctrl+C to stop)\n";
            host.loop();
        }else{
            rc=1;
        }
    } // Destroy our overlay handles while OpenVR is still initialized.
    vr::VR_Shutdown();
    return rc;
}
